import pyomo.environ as pyo

DATA = {
    "cities": ["A", "B", "C", "D", "E"],
    # directed travel cost cost[i][j], i != j (index order follows "cities")
    "cost": [
        [None, 95, 36, 93, 16],   # from A
        [95, None, 95, 29, 96],   # from B
        [36, 95, None, 72, 38],   # from C
        [93, 29, 72, None, 77],   # from D
        [16, 96, 38, 77, None],   # from E
    ],
    "big_m": 100,  # upper bound for MTZ order variables (number of cities)
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # --- Sets ---
    model.N = pyo.RangeSet(0, len(d["cities"]) - 1)
    model.A = pyo.Set(
        initialize=[(i, j) for i in range(len(d["cities"]))
                    for j in range(len(d["cities"])) if i != j],
        dimen=2,
    )
    # nodes eligible for MTZ ordering (all except the start node 0)
    model.Norder = pyo.RangeSet(1, len(d["cities"]) - 1)

    # --- Variables ---
    model.x = pyo.Var(model.A, within=pyo.Binary)

    # MTZ order variables: node 0 fixed to 1, others bounded in [2, n]
    n_cities = len(d["cities"])

    def u_bounds(m, i):
        if i == 0:
            return (1, 1)
        return (2, n_cities)

    model.u = pyo.Var(model.N, within=pyo.NonNegativeReals, bounds=u_bounds)

    # --- Objective: minimize total travel cost ---
    def obj_rule(m):
        return sum(d["cost"][i][j] * m.x[i, j] for (i, j) in m.A)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Constraints ---

    # Out-degree: each city must be departed exactly once (== 1)
    def out_rule(m, i):
        return sum(m.x[i, j] for j in range(n_cities) if j != i) == 1

    model.out_deg = pyo.Constraint(model.N, rule=out_rule)

    # In-degree: each city must be entered exactly once (== 1)
    def in_rule(m, j):
        return sum(m.x[i, j] for i in range(n_cities) if i != j) == 1

    model.in_deg = pyo.Constraint(model.N, rule=in_rule)

    # MTZ subtour elimination over the ordered nodes
    def mtz_rule(m, i, j):
        if i == j:
            return pyo.Constraint.Skip
        return m.u[j] >= m.u[i] + 1 - d["big_m"] * (1 - m.x[i, j])

    model.mtz = pyo.Constraint(model.Norder, model.Norder, rule=mtz_rule)

    return model


